def check(ctx):
    rgb = ctx.rgb()
    if rgb is None:
        return None
    if "ref" not in ctx.state:
        ctx.state["ref"] = rgb.copy()
        return None
    diff = np.abs(rgb.astype(np.float32) - ctx.state["ref"].astype(np.float32))
    changed = float(np.mean(diff))
    if changed > ctx.value("scene_change_level"):
        ctx.state["ref"] = rgb.copy()
        return {"value": changed, "detail": "workspace camera image changed significantly from reference"}
    return None

